  const startOfWeek = (()=>{const d=new Date(today+'T12:00:00'),dayNum=(d.getDay()+6)%7;d.setDate(d.getDate()-dayNum);return d.toLocaleDateString('en-CA')})();
  function weekAggregate(){const start=new Date(startOfWeek+'T12:00:00'),unique=new Set();let plays=0,brain=0,milestones=0,ratings=0,circuits=0;for(let i=0;i<7;i++){const d=new Date(start);d.setDate(start.getDate()+i);const key=d.toLocaleDateString('en-CA'),rec=dailyStore[key];if(!rec)continue;plays+=Number(rec.plays||0);brain+=Number(rec.brain||0);milestones+=Number(rec.milestones||0);ratings+=Number(rec.ratings||0);for(const id of rec.unique||[])unique.add(id);if(dailyCompleteFor(key,rec)===3)circuits++;}return{plays,unique:unique.size,brain,milestones,ratings,circuits}}
