  const metricValue = (c,d) => c.metric==='unique' ? (Array.isArray(d?.unique)?d.unique.length:0) : Number(d?.[c.metric]||0);
  function challengeSet(date){ let seed=0; for(const ch of date) seed=(seed*31+ch.charCodeAt(0))>>>0; const out=[], used=new Set(); while(out.length<3){ seed=(seed*1664525+1013904223)>>>0; const i=seed%challengePool.length; if(!used.has(i)){used.add(i);out.push(challengePool[i]);} } return out; }
  const dailyChallenges = challengeSet(today);
