  function renderLibrary(){ let list=games.filter(g=>(state.category==='All'||g.genres.includes(state.category))&&(state.input==='All'||capabilities(g).includes(state.input))&&(state.mode==='All'||playModes(g).includes(state.mode))&&(state.collection==='All'||(collections[state.collection]||collections.All)(g))&&(state.status==='All'||(state.status==='Unplayed'&&!state.plays[g.id])||(state.status==='In Progress'&&Number(state.plays[g.id]||0)>0&&!gameCleared(g))||(state.status==='Uncleared'&&!gameCleared(g))||(state.status==='Fresh Genre'&&freshPrimaryGenre(g))||(state.status==='Favorites'&&state.favorites.includes(g.id))||(state.status==='Cleared'&&gameCleared(g))||(state.status==='Play Later'&&state.playLater.includes(g.id)))&&(`${g.title} ${g.tagline} ${g.description} ${objectiveFor(g)} ${classicArchetypes[g.id]||''} ${g.genres.join(' ')}`).toLowerCase().includes(state.query.toLowerCase())); list.sort((a,b)=>state.sort==='new'?b.added.localeCompare(a.added)||b.basePopularity-a.basePopularity:state.sort==='popular'?(b.basePopularity+(state.plays[b.id]||0)*3)-(a.basePopularity+(state.plays[a.id]||0)*3):state.sort==='rated'?(state.ratings[b.id]||0)-(state.ratings[a.id]||0)||b.basePopularity-a.basePopularity:state.sort==='time'?(Number(state.playtime[b.id]||0)-Number(state.playtime[a.id]||0)||b.basePopularity-a.basePopularity):state.sort==='updated'?(String(b.updated||b.added).localeCompare(String(a.updated||a.added))||Number(!!b.version)-Number(!!a.version)||b.basePopularity-a.basePopularity):state.sort==='az'?a.title.localeCompare(b.title):Number(b.featured)-Number(a.featured)||b.basePopularity-a.basePopularity); $('#gameGrid').innerHTML=list.map(g=>gameCard(g)).join(''); $('#emptyState').hidden=!!list.length; wireFavorites(); wireLater(); }
  function renderChips(){ $('#categoryChips').innerHTML=categories.map(c=>`<button class="chip ${c===state.category?'active':''}" data-category="${esc(c)}">${esc(c)}</button>`).join(''); document.querySelectorAll('[data-category]').forEach(b=>b.addEventListener('click',()=>{state.category=b.dataset.category;syncDiscoveryUrl();renderChips();renderLibrary();})); }
