  function renderChallenges(){ const complete=dailyComplete(), streak=challengeStreak(); $('#challengeGrid').innerHTML=dailyChallenges.map(c=>{const v=Math.min(c.goal,metricValue(c,day)),done=v>=c.goal;return `<article class="challenge-card ${done?'complete':''}"><span class="challenge-mark">${done?'✓':'◇'}</span><div><strong>${esc(c.name)}</strong><p>${esc(c.desc)}</p><div class="challenge-progress"><i style="width:${Math.round(v/c.goal*100)}%"></i></div><small>${v}/${c.goal}</small></div></article>`}).join(''); $('#challengeNote').textContent=complete===3?`Daily circuit complete • ${Math.max(1,streak)} day streak.`:`${complete}/3 complete • current streak ${streak} day${streak===1?'':'s'}.`; if($('#streakPanel')) $('#streakPanel').innerHTML=`<strong>${streak}</strong><span>consecutive completed circuit day${streak===1?'':'s'}</span><small>Today's rotating set is generated locally and changes each day.</small>`; }
