  let installPrompt=null;const installButton=$('#installButton');addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;if(installButton)installButton.hidden=false});if(installButton)installButton.addEventListener('click',async()=>{if(!installPrompt)return;installPrompt.prompt();try{await installPrompt.userChoice}catch{}installPrompt=null;installButton.hidden=true});addEventListener('appinstalled',()=>{installPrompt=null;if(installButton)installButton.hidden=true});
  const keyChoices=[['KeyW','W'],['KeyA','A'],['KeyS','S'],['KeyD','D'],['KeyI','I'],['KeyJ','J'],['KeyK','K'],['KeyL','L'],['ArrowUp','↑'],['ArrowDown','↓'],['ArrowLeft','←'],['ArrowRight','→'],['Space','Space'],['Enter','Enter'],['ShiftLeft','Left Shift'],['KeyQ','Q'],['KeyE','E'],['KeyF','F'],['KeyC','C'],['KeyX','X'],['KeyZ','Z']],keyDefaults={up:'KeyW',down:'KeyS',left:'KeyA',right:'KeyD',primary:'Space',secondary:'KeyE'};
  // A profile import can contain arbitrary browser-local JSON, not just UI selections.
  // Invalid action values are ignored in memory without rewriting historical saves.
  const importedKeymap=state.keymap,availableCodes=new Set(keyChoices.map(([code])=>code));
  state.keymap=Object.fromEntries(Object.entries(importedKeymap&&typeof importedKeymap==='object'&&!Array.isArray(importedKeymap)?importedKeymap:{}).filter(([action,code])=>Object.hasOwn(keyDefaults,action)&&typeof code==='string'&&availableCodes.has(code)));

  function renderKeymap(){document.querySelectorAll('[data-key-action]').forEach(sel=>{const action=sel.dataset.keyAction,current=state.keymap[action]||keyDefaults[action];sel.innerHTML=keyChoices.map(([v,l])=>`<option value="${v}" ${v===current?'selected':''}>${l}</option>`).join('');sel.onchange=()=>{state.keymap[action]=sel.value;localStorage.setItem('wwg:keymap',JSON.stringify(state.keymap));renderPersonal()}});const reset=$('#resetKeymap');if(reset)reset.onclick=()=>{state.keymap={};localStorage.removeItem('wwg:keymap');renderKeymap();renderPersonal()}}
  renderKeymap();
  const exportData=$('#exportData');if(exportData)exportData.addEventListener('click',()=>{const data={version:2,exportedAt:new Date().toISOString(),data:{}};for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(k&&k.startsWith('wwg:')){const v=localStorage.getItem(k);if(v!=null)data.data[k]=v}}const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='worldwidegames-profile.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)});
  const importData=$('#importData'),importFile=$('#importFile');if(importData&&importFile){importData.addEventListener('click',()=>importFile.click());importFile.addEventListener('change',async()=>{const f=importFile.files&&importFile.files[0];if(!f)return;try{if(f.size>3000000)throw new Error('Profile too large');const obj=JSON.parse(await f.text());const result=importProfile(obj);if(!result.ok)throw new Error(result.error);location.reload()}catch{importData.textContent='Import failed';setTimeout(()=>importData.textContent='Import profile',1400)}})};
  addEventListener('keydown',e=>{if(e.key==='/'&&!/input|select|textarea/i.test(document.activeElement?.tagName||'')){e.preventDefault();$('#searchInput')?.focus()}if(e.code==='KeyP'&&!/input|select|textarea/i.test(document.activeElement?.tagName||'')){$('#profileButton')?.click()}});
  $('#clearData').addEventListener('click',()=>{for(let i=localStorage.length-1;i>=0;i--){const k=localStorage.key(i);if(k&&k.startsWith('wwg:'))localStorage.removeItem(k)}location.reload();});
  renderChips(); renderLibrary(); renderClassics(); renderDailyPick(); renderUpdated(); renderReleaseHistory(); renderPersonal(); renderRecommendations(); renderChallenges(); renderWeekly(); if('serviceWorker' in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('sw.js').catch(()=>{});
